"""Полный авторский сценарий лекционной части пилотного курса."""

PAGES = []

def page(title, module='', scene='', kind='scene'):
    p = dict(title=title, module=module, scene=scene, kind=kind, blocks=[])
    PAGES.append(p)
    return p

def para(p, text, label=None):
    p['blocks'].append(dict(type='para', text=text, label=label))

def bubble(p, text, optional=False):
    p['blocks'].append(dict(type='bubble', text=text, optional=optional))

def table(p, headers, rows, widths=None):
    p['blocks'].append(dict(type='table', headers=headers, rows=rows, widths=widths))

def check(p, cid, prompt, choices, correct, completion):
    p['blocks'].append(dict(type='check', id=cid, prompt=prompt,
                            choices=choices, correct=correct, completion=completion))


p = page('Расследование производственных происшествий', kind='front')
